// Chat is the resolver for the chat field.
func (r *repositoryResolver) Chat(ctx context.Context, obj *Repository, branch string, first int, after *string) (*ChatPage, error) {
	v, repoID, err := repoOf(ctx, obj)
	if err != nil {
		return nil, err
	}
	subj, err := r.Chats.Branch(ctx, v, repoID, branch)
	switch {
	case errors.Is(err, repos.ErrNotFound):
		return nil, nil
	case err != nil:
		return nil, fail(ctx, err, "branch", "reading the chat")
	}
	return r.chatPage(ctx, v, subj, first, after)
}

